const steps=[...wizard.querySelectorAll('.ew-step')];const serviceChoices=wizard.querySelector('.ew-service');const tintFields=wizard.querySelector('#ewTintFields');const removalGroup=wizard.querySelector('[data-key="removal"]');const locationGroup=wizard.querySelector('[data-key="location"]');const dateField=wizard.querySelector('#ewDate');const timeField=wizard.querySelector('#ewTime');
steps[0].innerHTML='<h3>What are we working on?</h3><p class="ew-helper">Choose the service for your vehicle.</p>';steps[0].appendChild(serviceChoices);
